import { computed, ref } from 'vue'
import { defineStore } from 'pinia'
import type { EnergyType } from '../mock/planningSheets'

export type { EnergyType } from '../mock/planningSheets'

/* ═══════════════════════════════════════════════════════════
 * 规划工作簿 store —— 规划工作表统一工作台的数据中枢
 * - 石油液体 / 天然气两部分数据相互独立
 * - Sheet3/11/12/13（气：2/7/8/9）分项产量 + Sheet14（气：10）自动汇总
 * - Sheet15/16/17（气：11/12/13）工作量
 * - 单元格来源标识：import 自动带入 / manual 人工填写 / ai AI 建议
 * - 版本快照 + 行级/单元格级 diff；AI 建议应用与撤销
 * ═══════════════════════════════════════════════════════════ */

export type DataKind = 'base' | 'adjustment' | 'measure' | 'development'
export type WorkloadKind = 'adjustment' | 'measure' | 'development'
export type CellSource = 'import' | 'manual' | 'ai'

export const DATA_KIND_LABELS: Record<DataKind, string> = {
  base: '基础产量',
  adjustment: '调整井产量',
  measure: '措施产量',
  development: '开发井产量',
}

export const WORKLOAD_LABELS: Record<WorkloadKind, string> = {
  adjustment: '调整井工作量（口）',
  measure: '措施工作量（井次）',
  development: '开发井工作量（口）',
}

export interface YearCell {
  v: number
  src: CellSource
}

export interface PlanningFieldRow {
  id: string
  oilfield: string
  alias: string
  area: string
  state: string
  /** 投产时间（年），可自定义；null 表示缺失（闭合校验会报错误） */
  commissioningYear: number | null
  data: Record<DataKind, Record<string, YearCell>>
  workload: Record<WorkloadKind, Record<string, number>>
  updatedBy: string
  updatedAt: string
}

export interface WorkbookVersion {
  id: string
  name: string
  state: '正式' | '草案'
  createdAt: string
  createdBy: string
  note: string
  snapshot: Record<EnergyType, PlanningFieldRow[]>
}

export type ClosureLevel = 'error' | 'warning'

export interface ClosureIssue {
  id: string
  level: ClosureLevel
  rowId: string
  oilfield: string
  area: string
  year: string
  kind: DataKind | 'total' | 'workload'
  message: string
  suggestion: string
}

export interface AiImpact {
  rowId: string
  oilfield: string
  kind: DataKind
  year: string
  before: number
  after: number
}

export interface AiSuggestion {
  id: string
  title: string
  summary: string
  basis: string
  sourceRef: string
  impacts: AiImpact[]
  risks: string[]
  confidence: number
  needConfirm: string
  status: 'pending' | 'applied' | 'discarded'
}

export type DiffKind = DataKind | `wl-${WorkloadKind}`

export interface CellDiff {
  kind: DiffKind
  year: string
  before: number
  after: number
}

export interface RowDiff {
  rowId: string
  oilfield: string
  area: string
  changeType: 'added' | 'removed' | 'modified' | 'same'
  cells: CellDiff[]
}

const DATA_KINDS: DataKind[] = ['base', 'adjustment', 'measure', 'development']
const WORKLOAD_KINDS: WorkloadKind[] = ['adjustment', 'measure', 'development']

function blankYearData(years: string[], fill = 0, src: CellSource = 'import'): Record<DataKind, Record<string, YearCell>> {
  const data = {} as Record<DataKind, Record<string, YearCell>>
  for (const kind of DATA_KINDS) {
    data[kind] = {}
    for (const year of years) data[kind][year] = { v: fill, src }
  }
  return data
}

function blankWorkload(years: string[]): Record<WorkloadKind, Record<string, number>> {
  const workload = {} as Record<WorkloadKind, Record<string, number>>
  for (const kind of WORKLOAD_KINDS) {
    workload[kind] = {}
    for (const year of years) workload[kind][year] = 0
  }
  return workload
}

function cloneRows(rows: PlanningFieldRow[]): PlanningFieldRow[] {
  return JSON.parse(JSON.stringify(rows)) as PlanningFieldRow[]
}

/** 单行单年总产量（Sheet14 = 3+11+12+13） */
export function rowYearTotal(row: PlanningFieldRow, year: string): number {
  return Number(DATA_KINDS.reduce((sum, kind) => sum + (row.data[kind][year]?.v ?? 0), 0).toFixed(2))
}

interface SeedRow {
  id: string
  oilfield: string
  alias: string
  area: string
  state: string
  commissioningYear: number | null
  base: number[]
  adjustment: number[]
  measure: number[]
  development: number[]
  wlAdjustment: number[]
  wlMeasure: number[]
  wlDevelopment: number[]
}

const DEFAULT_YEARS = ['2025', '2026', '2027', '2028', '2029', '2030']

function seedRows(seeds: SeedRow[], years: string[]): PlanningFieldRow[] {
  return seeds.map((seed) => {
    const data = blankYearData(years)
    const workload = blankWorkload(years)
    years.forEach((year, index) => {
      data.base[year] = { v: seed.base[index] ?? 0, src: 'import' }
      data.adjustment[year] = { v: seed.adjustment[index] ?? 0, src: 'import' }
      data.measure[year] = { v: seed.measure[index] ?? 0, src: 'import' }
      data.development[year] = { v: seed.development[index] ?? 0, src: 'import' }
      workload.adjustment[year] = seed.wlAdjustment[index] ?? 0
      workload.measure[year] = seed.wlMeasure[index] ?? 0
      workload.development[year] = seed.wlDevelopment[index] ?? 0
    })
    return {
      id: seed.id,
      oilfield: seed.oilfield,
      alias: seed.alias,
      area: seed.area,
      state: seed.state,
      commissioningYear: seed.commissioningYear,
      data,
      workload,
      updatedBy: '综合规划室 · 李四',
      updatedAt: '2026-07-24 17:20',
    }
  })
}

