/** 计算两版本行级/单元格级差异（纯函数，便于测试） */
export function diffVersionRows(before: PlanningFieldRow[], after: PlanningFieldRow[]): RowDiff[] {
  const diffs: RowDiff[] = []
  const beforeMap = new Map(before.map((row) => [row.id, row]))
  const afterMap = new Map(after.map((row) => [row.id, row]))

  for (const row of after) {
    const prev = beforeMap.get(row.id)
    if (!prev) {
      diffs.push({ rowId: row.id, oilfield: row.oilfield, area: row.area, changeType: 'added', cells: [] })
      continue
    }
    const cells: CellDiff[] = []
    for (const kind of DATA_KINDS) {
      const years = new Set([...Object.keys(row.data[kind]), ...Object.keys(prev.data[kind])])
      for (const year of years) {
        const b = prev.data[kind][year]?.v ?? 0
        const a = row.data[kind][year]?.v ?? 0
        if (Math.abs(a - b) > 1e-9) cells.push({ kind, year, before: b, after: a })
      }
    }
    for (const kind of WORKLOAD_KINDS) {
      const years = new Set([...Object.keys(row.workload[kind]), ...Object.keys(prev.workload[kind])])
      for (const year of years) {
        const b = prev.workload[kind][year] ?? 0
        const a = row.workload[kind][year] ?? 0
        if (Math.abs(a - b) > 1e-9) cells.push({ kind: `wl-${kind}`, year, before: b, after: a })
      }
    }
    diffs.push({ rowId: row.id, oilfield: row.oilfield, area: row.area, changeType: cells.length ? 'modified' : 'same', cells })
  }
  for (const row of before) {
    if (!afterMap.has(row.id)) {
      diffs.push({ rowId: row.id, oilfield: row.oilfield, area: row.area, changeType: 'removed', cells: [] })
    }
  }
  return diffs
}

/** 汇总闭合校验（纯函数，便于测试）：正常 / 警告 / 错误 三种状态 */
export function checkClosure(rows: PlanningFieldRow[], years: string[]): ClosureIssue[] {
  const issues: ClosureIssue[] = []
  let seq = 0
  for (const row of rows) {
    if (row.commissioningYear === null) {
      issues.push({ id: `ci-${(seq += 1)}`, level: 'error', rowId: row.id, oilfield: row.oilfield, area: row.area, year: '-', kind: 'total', message: '投产时间（年）缺失，无法参与汇总闭合。', suggestion: '在基础数据或工作表中补齐投产时间。' })
    }
    for (const year of years) {
      const dev = row.data.development[year]?.v ?? 0
      const devWorkload = row.workload.development[year] ?? 0
      if (dev > 0 && devWorkload === 0) {
        issues.push({ id: `ci-${(seq += 1)}`, level: 'error', rowId: row.id, oilfield: row.oilfield, area: row.area, year, kind: 'workload', message: `${year} 年开发井产量 ${dev}，但 Sheet17 开发井工作量为 0，产量与工作量不闭合。`, suggestion: '补充开发井工作量，或将开发井产量清零。' })
      }
      const base = row.data.base[year]?.v ?? 0
      const measure = row.data.measure[year]?.v ?? 0
      if (base > 0 && measure > base * 0.5) {
        issues.push({ id: `ci-${(seq += 1)}`, level: 'warning', rowId: row.id, oilfield: row.oilfield, area: row.area, year, kind: 'measure', message: `${year} 年措施产量占基础产量比例过高（${Math.round((measure / base) * 100)}%）。`, suggestion: '复核措施剖面与井次安排，必要时附说明。' })
      }
      const idx = years.indexOf(year)
      if (idx > 0) {
        const prevTotal = rowYearTotal(row, years[idx - 1])
        const currTotal = rowYearTotal(row, year)
        if (prevTotal > 0 && Math.abs(currTotal - prevTotal) / prevTotal > 0.45) {
          issues.push({ id: `ci-${(seq += 1)}`, level: 'warning', rowId: row.id, oilfield: row.oilfield, area: row.area, year, kind: 'total', message: `${year} 年总产量环比波动超过 45%（${prevTotal.toFixed(1)} → ${currTotal.toFixed(1)}）。`, suggestion: '确认新投产或递减假设，并在版本说明中记录。' })
        }
      }
    }
  }
  return issues
}

