const STORAGE_KEY = 'aoqin-demo-user'

function readStoredUser() {
  if (typeof window === 'undefined') return null
  const raw = window.localStorage.getItem(STORAGE_KEY)
  if (!raw) return null

  try {
    const stored = JSON.parse(raw) as Partial<DemoUser>
    const canonical = mockUsers.find((user) => user.id === stored.id)
    if (!canonical) {
      window.localStorage.removeItem(STORAGE_KEY)
      return null
    }
    // Earlier demos persisted the whole user object, allowing renamed sample users to survive upgrades.
    window.localStorage.setItem(STORAGE_KEY, JSON.stringify(canonical))
    return canonical
  } catch {
    window.localStorage.removeItem(STORAGE_KEY)
    return null
  }
}

export const useAuthStore = defineStore('auth', () => {
  // The demo opens on a full-access account so reviewers can see the complete
  // product surface. Existing role accounts remain selectable from the header.
  const currentUser = ref<DemoUser | null>(readStoredUser() ?? mockUsers[0])

  const roleLabel = computed(() => currentUser.value?.roleName || '未登录')

  function login(userId: string) {
    const user = mockUsers.find((item) => item.id === userId) || mockUsers[0]
    currentUser.value = user
    if (typeof window !== 'undefined') {
      window.localStorage.setItem(STORAGE_KEY, JSON.stringify(user))
    }
  }

  function logout() {
    currentUser.value = null
    if (typeof window !== 'undefined') {
      window.localStorage.removeItem(STORAGE_KEY)
    }
  }

  return {
    currentUser,
    roleLabel,
    login,
    logout,
  }
})

