import type { DemoUser } from './users'
import type { PermissionAction } from '../types/templateModel'

export type AppRouteKey = 'dashboard' | 'reserve' | 'planning' | 'admin'

type RolePermission = {
  routes: AppRouteKey[]
  actions: PermissionAction[]
  editableFields: string[]
}

const rolePermissions: Record<string, RolePermission> = {
  demo_super_admin: { routes: ['dashboard', 'reserve', 'planning', 'admin'], actions: ['view', 'edit', 'import', 'validate', 'submit', 'publish', 'export', 'configure'], editableFields: ['reserve.*', 'planning.*'] },
  reserve_analyst: { routes: ['dashboard', 'reserve'], actions: ['view', 'edit', 'import', 'validate', 'submit', 'export'], editableFields: ['reserve.*'] },
  planning_specialist: { routes: ['dashboard', 'planning'], actions: ['view', 'edit', 'import', 'validate', 'submit', 'export'], editableFields: ['planning.*'] },
  area_coordinator: { routes: ['dashboard', 'planning'], actions: ['view', 'edit', 'validate', 'submit', 'export'], editableFields: ['planning.*'] },
  field_owner: { routes: ['dashboard', 'planning'], actions: ['view', 'edit', 'validate', 'submit'], editableFields: ['planning.base', 'planning.adjustment', 'planning.measure', 'planning.workload'] },
  manager_viewer: { routes: ['dashboard', 'reserve', 'planning', 'admin'], actions: ['view', 'export'], editableFields: [] },
  system_admin: { routes: ['dashboard', 'admin'], actions: ['view', 'configure', 'publish'], editableFields: [] },
}

export function canPerformAction(user: DemoUser | null | undefined, action: PermissionAction) {
  return Boolean(user && rolePermissions[user.roleKey]?.actions.includes(action))
}

export function canEditField(user: DemoUser | null | undefined, fieldKey: string) {
  if (!user) return false
  const fields = rolePermissions[user.roleKey]?.editableFields ?? []
  return fields.includes(fieldKey) || fields.some((item) => item.endsWith('.*') && fieldKey.startsWith(item.slice(0, -1)))
}

export function getVisibleRoutes(user: DemoUser | null | undefined) {
  if (!user) return []
  return rolePermissions[user.roleKey]?.routes ?? []
}

export function canVisitPath(user: DemoUser | null | undefined, path: string) {
  const key: AppRouteKey = path.startsWith('/reserve') ? 'reserve' : path.startsWith('/planning') ? 'planning' : path.startsWith('/admin') ? 'admin' : 'dashboard'
  return getVisibleRoutes(user).includes(key)
}

/**
 * 油/气区名称对齐：天然气种子可用「示例气区甲」，账号 scope 多为「示例油区甲」。
 * Demo 约定：气区甲 ≡ 油区甲（按甲/乙后缀对齐），避免切天然气后权限全锁死。
 */
export function normalizeAreaKey(area: string) {
  return area.replace(/气区/g, '油区').trim()
}

export function areaInUserScope(user: DemoUser | null | undefined, area: string) {
  if (!user) return false
  if (!user.areaScope.length) return true
  const key = normalizeAreaKey(area)
  return user.areaScope.some((item) => item === area || normalizeAreaKey(item) === key)
}

export function filterByScope<T extends { area?: string; oilfield?: string }>(records: T[], user: DemoUser | null | undefined) {
  if (!user) return []
  return records.filter((record) => {
    const areaAllowed = !user.areaScope.length || (record.area ? areaInUserScope(user, record.area) : false)
    const fieldAllowed = !user.fieldScope.length || (record.oilfield && user.fieldScope.includes(record.oilfield))
    return Boolean(areaAllowed && fieldAllowed)
  })
}

/** 是否可编辑指定油区数据（Sheet11-17 按油区管控：公司级可编辑全部，油区角色仅本油区） */
export function canEditArea(user: DemoUser | null | undefined, area: string) {
  if (!user) return false
  if (!canPerformAction(user, 'edit')) return false
  return areaInUserScope(user, area)
}

/** 是否可查看指定油区数据（无权限数据在页面上脱敏或只读展示） */
export function canViewArea(user: DemoUser | null | undefined, area: string) {
  if (!user) return false
  return areaInUserScope(user, area)
}

/** 油区范围文案：用于权限状态展示 */
export function areaScopeLabel(user: DemoUser | null | undefined) {
  if (!user) return '未登录'
  return user.areaScope.length ? user.areaScope.join('、') : '全部油区（公司级）'
}

/** 无权限操作的原因提示 */
export function deniedReason(user: DemoUser | null | undefined, area: string) {
  if (!user) return '未登录，无法操作。'
  if (!canPerformAction(user, 'edit')) return `当前角色「${user.roleName}」为只读权限，不能编辑规划数据。`
  if (user.areaScope.length && !areaInUserScope(user, area)) {
    return `当前账号仅授权【${user.areaScope.join('、')}】，Sheet11-17 按油区管控，无法编辑 ${area} 数据。`
  }
  return ''
}

