  console.log('\nReport:', outJson)
  console.log('Console errors:', report.consoleErrors.length)
  await browser.close()

  const failed = report.flows.filter((f) => f.status === 'FAIL')
  process.exit(failed.length ? 1 : 0)
}

main()

import { readdir, readFile } from 'node:fs/promises'
import { extname, join, relative } from 'node:path'
import process from 'node:process'

const roots = ['src', 'dist']
const allowedExtensions = new Set(['.ts', '.vue', '.js', '.json', '.html', '.css'])
const forbidden = [
  '惠州26-1',
  '西江30-2',
  '番禺4-2',
  '陆丰13-8',
  '真实解析内容',
  '真实内容已载入',
  '真实读取 Sheet',
  'realTemplateData.json',
]

async function walk(root) {
  const entries = await readdir(root, { withFileTypes: true })
  const files = []
  for (const entry of entries) {
    const path = join(root, entry.name)
    if (entry.isDirectory()) files.push(...await walk(path))
    else if (allowedExtensions.has(extname(entry.name))) files.push(path)
  }
  return files
}

const hits = []
for (const root of roots) {
  for (const file of await walk(root)) {
    const content = await readFile(file, 'utf8')
    for (const token of forbidden) {
      if (content.includes(token)) hits.push(`${relative('.', file)}: ${token}`)
    }
  }
}

if (hits.length) {
  console.error(`数据边界检查失败：\n${hits.join('\n')}`)
  process.exit(1)
}

console.log(`数据边界检查通过：已扫描 ${roots.join('、')}。`)

