    const fields = auth.currentUser?.fieldScope ?? []
    if (!areas.length && !fields.length) return true
    return areas.includes(row.area) || fields.includes(row.oilfield)
  })
  const total = scopeRows.reduce((sum, row) => sum + rowYearTotal(row, year), 0)
